import { gunzipSync } from 'node:zlib';
import { experimental_AstroContainer as AstroContainer } from 'astro/container';
import { expect, it } from 'vitest';
import { allPieces, volumeLabel, pagesLabel, relatedHymnSettings, type Piece } from './catalog';
import { allLineups, hymnSettings, type LineupItem } from './vespers';
import SystemStack from '../components/SystemStack.astro';
import LineupStack from '../components/LineupStack.astro';

const words = (html: string) => html.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
const captions = (html: string) => [...html.matchAll(/<(figcaption|p|div)\b[^>]*(?:class="(?:sr-only|notice[^"]*)"|role="status")[^>]*>([\s\S]*?)<\/\1>/g)].map(m => words(m[2]!));
it('matches the captured pre-change labels, captions, credits and hymn-link order', async () => {
  const container = await AstroContainer.create();
  const pieces = [];
  for (const p of allPieces()) pieces.push({ slug: p.slug, volume: volumeLabel(p), pages: pagesLabel(p), related: relatedHymnSettings(p).map(x => x.slug), captions: captions(await container.renderToString(SystemStack, { props: { piece: p } })) });
  const lineups = [];
  for (const day of allLineups()) lineups.push({ key: `${day.date}/${day.vespers}`, links: day.items.map(i => hymnSettings(i).map(p => p.slug)), captions: captions(await container.renderToString(LineupStack, { props: { day } })) });
  expect({pieces, lineups}).toEqual(baseline);
  expect(pieces).toHaveLength(576);
  expect(lineups).toHaveLength(578);
}, 120000);

// Captured before S on d41928bda89cb49e67d9ad4a6d9fdbeedb7a61e8: 576 pieces, 578 lineups, 7,477 rendered captions.
// Frozen values, gzip encoded to keep the complete fixture compact. Never regenerated by tests.
const baseline: unknown = JSON.parse(gunzipSync(Buffer.from(
  "",
  "base64")).toString());

it('accepts an available non-NOH reviewed hymn in both selection paths', () => {
  const original = allPieces().find(p => p.genre === 'hymn' && p.systems.length && !p.sourceNote)!;
  const foreign: Piece = { ...original, volume: 'test-hymnal' };
  const source = allPieces().find(p => relatedHymnSettings(p).some(h => h.slug === original.slug))!;
  expect(relatedHymnSettings(source, [foreign]).map(p => p.slug)).toEqual([foreign.slug]);
  const item: LineupItem = { ...allLineups()[0]!.items[0]!, hymnLinks: [foreign.slug] };
  expect(hymnSettings(item, [foreign]).map(p => p.slug)).toEqual([foreign.slug]);
});

it('rejects unknown edition labels rather than crediting them to NOH', () => {
  expect(() => volumeLabel({ ...allPieces()[0]!, volume: 'unregistered' })).toThrow(/edition/i);
});

it('preserves both NOH3 addenda labels', () => {
  const addenda = allPieces().filter(p => p.volume === 'noh3' && p.pagination);
  expect(new Set(addenda.map(p => p.slug))).toEqual(new Set(['b-mariae-virginis-reginae', 's-pii-x-papae-et-confessoris']));
  expect(addenda.map(p => [volumeLabel(p), pagesLabel(p)])).toEqual([
    ['Nova Organi Harmonia, part III', 'Addenda ad Partem III, pp. 3–11'],
    ['Nova Organi Harmonia, part III', 'Addenda ad Partem III, pp. 3–11'],
  ]);
});

it('reads edition labels, part-less and no-source fallbacks and policies from the registry', async () => {
  const { sourceRegistry, parseSources, editionPolicy, sourceLabel, borrowedVolumeLabel } = await import('./identities');
  const edition = { ...sourceRegistry.editions[0]!, id: 'edn_fixture', legacy_volume: 'test-hymnal', scan_registry_key: 'test-hymnal', adapter: 'fixture', part: null, citation_label: 'Fixture hymnal', short_label: 'Fixture' };
  const registry = parseSources({ ...sourceRegistry, editions: [...sourceRegistry.editions, edition] });
  expect(sourceLabel('test-hymnal', registry)).toBe('Fixture hymnal');
  expect(volumeLabel({ ...allPieces()[0]!, volume: 'test-hymnal' }, registry)).toBe('Fixture hymnal');
  expect(sourceLabel(undefined)).toBe('Nova Organi Harmonia');
  expect(sourceLabel('test-hymnal', { ...registry, editions: [{ ...edition, citation_label: 'Nova Organi Harmonia' }] })).toBe('Nova Organi Harmonia');
  expect(borrowedVolumeLabel(null)).toBe('another volume');
  expect(borrowedVolumeLabel('noh3')).toBe('Nova Organi Harmonia, part III');
  expect(editionPolicy('noh7').borrow_whole_reference).toBe(false);
  expect(editionPolicy('noh8').related_hymns_heading).toBe('Related hymn settings in Book VII');
  expect(() => editionPolicy('missing')).toThrow(/edition/i);
  expect(() => parseSources({ ...sourceRegistry, editions: [{ ...edition, policy: { ...edition.policy, show_related_hymns: 'yes' } }] })).toThrow();
  expect(() => parseSources({ ...sourceRegistry, editions: [edition, edition] })).toThrow();
  expect(() => parseSources({ ...sourceRegistry, editions: [{ ...edition, scan_registry_key: "test-hymnal\n" }] })).toThrow();
});

it('uses registered hyphenated refs for admin ranges, previews, borrowing and hymn pairings', async () => {
  const { targets, piece } = await import('./admin/testing');
  const { checkValue, describeTarget, checkSections } = await import('./admin/targets');
  const scansModule = await import('./admin/scans');
  const { parseHymnPairings } = await import('./hymnpairings');
  const known = new Set(['test-hymnal', 'noh1']);
  const refs = ['test-hymnal/0001/000', 'test-hymnal/0001/001', 'test-hymnal/0001/002'];
  const t = targets(piece('fixture', { range: [refs[0]!, refs[1]!] }));
  const info = describeTarget(t, 'piece:fixture')!;
  expect(checkValue(t, info, 'system_range', `${refs[0]}-${refs[2]}`, known)).toEqual({ ok: true, value: `${refs[0]}-${refs[2]}` });
  expect(checkValue(t, info, 'system_range', `${refs[2]}-${refs[0]}`, known).ok).toBe(false);
  expect(checkValue(t, info, 'system_range', `${refs[0]}-noh1/0001/001`, known).ok).toBe(false);
  expect(checkValue(t, info, 'system_range', 'unknown/0001/000-unknown/0001/001', known).ok).toBe(false);
  expect(checkSections(info, JSON.stringify([{kind: 'hymn', borrowed_volume: 'test-hymnal', borrowed_page: 1}]), known).ok).toBe(true);
  const scans = { base: '/systems', order: refs, hash: ['', '', ''], aspect: [[1, 1], [1, 1], [1, 1]] as const, pieces: {fixture: [0, 2] as const}, movements: {} };
  expect(scansModule.namedSystems(scans, info, 'system_range', `${refs[0]}-${refs[2]}`, known).map(s => s.ref)).toContain(refs[2]);
  const row = { slug: 'fixture', title: 'Fixture', id: null, status: 'unresolved', incipit: null, mode: null, evidence: 'Fixture', sources: ['https://example.test'], copyrighted: null };
  expect(parseHymnPairings({ pairings: { [refs[0]!]: row } }, known).has(refs[0]!)).toBe(true);
  expect(() => parseHymnPairings({ pairings: { 'unknown/0001/000': row } }, known)).toThrow();
});

it('renders borrowed and part-less captions from an in-memory edition without changing the NOH fallbacks', async () => {
  const { sourceRegistry } = await import('./identities');
  const editions = sourceRegistry.editions;
  const fixture = { ...editions[0]!, id: 'edn_fixture', legacy_volume: 'test-hymnal', scan_registry_key: 'test-hymnal', adapter: 'fixture', part: null, citation_label: 'Fixture hymnal', short_label: 'Fixture' };
  Object.defineProperty(sourceRegistry, 'editions', { value: [...editions, fixture], configurable: true });
  try {
    const container = await AstroContainer.create();
    const piece: Piece = { ...allPieces()[0]!, id: 'fixture', slug: 'fixture', volume: 'test-hymnal', genre: 'hymn',
      title: 'Fixture hymn', mode: null, printedPages: [1, 1], pagination: null, systems: ['test-hymnal/0001/000'],
      systemAssets: [''], systemAspect: [[100, 20]], movements: [], hymns: [], chant: [],
      parts: [
        { kind: 'borrowed', part: 'hymn', variant: '', label: null, title: null, borrowedFrom: null, borrowedRef: null, borrowedVolume: 'noh3', borrowedPage: 7, gregobaseId: null },
        { kind: 'borrowed', part: 'hymn', variant: '2', label: null, title: null, borrowedFrom: null, borrowedRef: null, borrowedVolume: null, borrowedPage: 9, gregobaseId: null },
      ] };
    const html = words(await container.renderToString(SystemStack, { props: { piece } }));
    expect(html).toContain('organ accompaniment from Fixture hymnal, pp. 1–1');
    expect(html).toContain('the book refers to Nova Organi Harmonia, part III, printed page 7.');
    expect(html).toContain('the book refers to another volume, printed page 9.');
    expect(html).toContain('1942 printed score');
    Object.defineProperty(sourceRegistry, 'editions', { value: [...editions, { ...fixture, citation_label: 'Nova Organi Harmonia' }], configurable: true });
    const partless = words(await container.renderToString(SystemStack, { props: { piece: { ...piece, parts: [] } } }));
    expect(partless).toContain('organ accompaniment from Nova Organi Harmonia, pp. 1–1');
  } finally { Object.defineProperty(sourceRegistry, 'editions', { value: editions, configurable: true }); }
});
